"""SOLIDWORKS-style materials.

* Registers FreeWorks' own material library (Resources/Materials, generated by
  tools/make_materials.py) with FreeCAD's material system, so cards carry SOLIDWORKS names
  ("AISI 1020", "6061 Alloy", "1060 Alloy", "Copper"...) and densities.
* Assigns materials to bodies (Body.ShapeMaterial - FreeCAD also updates the appearance) or a
  custom density (stored on the body as FreeWorks properties, like a SOLIDWORKS custom material).
* material_of(obj) is what Mass Properties uses.
"""
import os

import FreeCAD as App

from . import MOD_DIR, log, icon_path

LIB_NAME = "FreeWorks"
LIB_DIR = os.path.join(MOD_DIR, "Resources", "Materials")
MODULES = "User parameter:BaseApp/Preferences/Mod/Material/Resources/Modules/" + LIB_NAME
CATEGORIES = ["Steel", "Iron", "Aluminium Alloys", "Copper Alloys", "Titanium Alloys", "Plastics", "Rubber"]
DEFAULT_DENSITY = 1000.0          # kg/m^3 - SOLIDWORKS' density when no material is assigned
NOT_SPECIFIED = "<not specified>"
PROP_NAME, PROP_DENSITY = "FW_Material", "FW_Density"   # custom material on a body
_cards = None


# ------------------------------------------------------------------ library
def register():
    """Make FreeCAD load the FreeWorks library. Cheap when already registered."""
    g = App.ParamGet(MODULES)
    changed = g.GetString("ModuleDir", "") != LIB_DIR
    if changed:
        g.SetString("ModuleDir", LIB_DIR)
        g.SetBool("ModuleReadOnly", True)
        ic = icon_path("freeworks")
        if ic:
            g.SetString("ModuleIcon", ic)
    try:
        import Materials
        mm = Materials.MaterialManager()
        if not any(_lib_name(lib) == LIB_NAME for lib in mm.MaterialLibraries):
            mm.refresh()
            log("material library registered: %s" % LIB_DIR)
    except Exception as e:  # material system unavailable: Mass Properties falls back to custom density
        log("material library: %s" % e)


def _lib_name(lib):
    return lib[0] if isinstance(lib, (tuple, list)) else getattr(lib, "Name", str(lib))


def cards():
    """FreeWorks cards: list of dicts (category, name, uuid, density, props), read from the files."""
    global _cards
    if _cards is not None:
        return _cards
    out = []
    for cat in CATEGORIES:
        d = os.path.join(LIB_DIR, cat)
        if not os.path.isdir(d):
            continue
        for fn in sorted(os.listdir(d)):
            if fn.endswith(".FCMat"):
                c = _parse(os.path.join(d, fn))
                if c:
                    c["category"] = cat
                    out.append(c)
    _cards = out
    return out


def _parse(path):
    c = {"props": {}}
    section = None
    with open(path, encoding="utf-8") as f:
        for line in f:
            s = line.strip()
            if not s or s.startswith("#") or s == "---":
                continue
            indent = len(line) - len(line.lstrip())
            if indent == 0:
                section = s.rstrip(":")
                continue
            if ":" not in s:
                continue
            k, v = s.split(":", 1)
            v = v.strip().strip('"').strip("'")
            if section == "General" and k in ("UUID", "Name", "Description"):
                c[k.lower()] = v
            elif section == "Models" and indent >= 4 and k != "UUID":
                c["props"][k] = v
    if "uuid" not in c or "Density" not in c["props"]:
        return None
    c["density"] = float(c["props"]["Density"].split()[0])
    return c


def card_by_name(name):
    for c in cards():
        if c["name"] == name:
            return c
    return None


def get(uuid):
    import Materials
    return Materials.MaterialManager().getMaterial(uuid)


def freecad_materials():
    """Other libraries' materials that have a density: [(library/path, name, uuid, density kg/m3)]."""
    out = []
    try:
        import Materials
        for uid, m in Materials.MaterialManager().Materials.items():
            if getattr(m, "LibraryName", "") == LIB_NAME:
                continue
            d = m.PhysicalProperties.get("Density") if m.PhysicalProperties else None
            if not d or m.Name in ("Default", ""):
                continue
            try:
                rho = App.Units.Quantity(d).getValueAs("kg/m^3").Value
            except Exception:
                continue
            folder = "%s/%s" % (m.LibraryName, os.path.dirname(getattr(m, "Directory", "") or ""))
            out.append((folder.rstrip("/"), m.Name, uid, rho))
    except Exception as e:
        log("FreeCAD materials: %s" % e)
    return sorted(out)


# ------------------------------------------------------------------ targets
def _bodies_in(obj, seen=None):
    seen = seen if seen is not None else set()
    if obj is None or obj in seen:
        return []
    seen.add(obj)
    if obj.isDerivedFrom("PartDesign::Body"):
        return [obj]
    if obj.isDerivedFrom("PartDesign::Feature"):
        b = obj.getParentGeoFeatureGroup() if hasattr(obj, "getParentGeoFeatureGroup") else None
        return [b] if b is not None and b.isDerivedFrom("PartDesign::Body") else []
    if obj.TypeId == "App::Link" or obj.isDerivedFrom("App::Link"):
        return _bodies_in(obj.getLinkedObject(True), seen)
    if hasattr(obj, "Group") and (obj.isDerivedFrom("App::Part") or obj.isDerivedFrom("App::DocumentObjectGroup")):
        out = []
        for ch in obj.Group:
            out += _bodies_in(ch, seen)
        return out
    if obj.isDerivedFrom("Part::Feature"):
        shp = getattr(obj, "Shape", None)
        if shp is not None and not shp.isNull() and shp.Solids:
            return [obj]
    return []


def targets():
    """Bodies the material dialog applies to: selection, else every body of the active part."""
    import FreeCADGui as Gui
    out = []
    for s in Gui.Selection.getSelectionEx("", 0):
        names = [n[:n.rfind(".") + 1] for n in s.SubElementNames if n] or [""]
        for path in names:
            o = s.Object.getSubObject(path, retType=1) if path else s.Object
            o = o[0] if isinstance(o, tuple) else o
            for b in _bodies_in(o):
                if b not in out:
                    out.append(b)
    if out:
        return out
    doc = App.ActiveDocument
    if doc is None:
        return []
    if any(o.TypeId == "Assembly::AssemblyObject" for o in doc.Objects):
        return []                      # assemblies: pick components first (SOLIDWORKS edits part materials)
    out = [o for o in doc.Objects if o.isDerivedFrom("PartDesign::Body")]
    return out or [o for o in doc.RootObjects if _bodies_in(o) == [o]]


# ------------------------------------------------------------------ assign / read
def apply(objs, uuid):
    mat = get(uuid)
    for o in objs:
        _clear_custom(o)
        o.ShapeMaterial = mat
    _touch(objs)
    return mat.Name


def apply_custom(objs, name, density):
    for o in objs:
        if not hasattr(o, PROP_NAME):
            o.addProperty("App::PropertyString", PROP_NAME, "FreeWorks", "Custom material name")
        if not hasattr(o, PROP_DENSITY):
            o.addProperty("App::PropertyFloat", PROP_DENSITY, "FreeWorks", "Custom density in kg/m^3")
        setattr(o, PROP_NAME, name or "Custom")
        setattr(o, PROP_DENSITY, float(density))
    _touch(objs)


def remove(objs):
    default = None
    try:
        import Materials
        mm = Materials.MaterialManager()
        default = next((m for m in mm.Materials.values() if m.Name == "Default" and getattr(m, "LibraryName", "") == "System"), None)
    except Exception:
        pass
    for o in objs:
        _clear_custom(o)
        if default is not None:
            try:
                o.ShapeMaterial = default
            except Exception:
                pass
    _touch(objs)


def _clear_custom(o):
    for p in (PROP_NAME, PROP_DENSITY):
        if hasattr(o, p):
            try:
                o.removeProperty(p)
            except Exception:
                pass


def _touch(objs):
    docs = {o.Document for o in objs}
    for d in docs:
        d.recompute()


def material_of(obj):
    """(material name, density kg/m^3). Custom density first, then the assigned material;
    FreeCAD's placeholder "Default" material (1 kg/m^3) means "not specified" -> 1000 kg/m^3."""
    for o in (obj, getattr(obj, "Tip", None)):
        if o is None:
            continue
        if getattr(o, PROP_DENSITY, 0) > 0:
            return getattr(o, PROP_NAME, "Custom") or "Custom", float(getattr(o, PROP_DENSITY))
        try:
            m = o.ShapeMaterial
            if not m or m.Name in ("", "Default"):
                continue
            d = m.PhysicalProperties.get("Density") if m.PhysicalProperties else None
            if d:
                return m.Name, App.Units.Quantity(d).getValueAs("kg/m^3").Value
        except Exception:
            pass
    return NOT_SPECIFIED, DEFAULT_DENSITY
